package org.deeptimeline.app
fun main(){val base=TimelineEvent(title="fraction",moment=Moment(0,0),civil="1970-01-01T00:00",mode="UTC",coords="",zone="UTC",offsetNano="0",maxScaleAmount="1/3",maxScaleUnit="DAY");check(VisibilityScale.normalize("0.(3)","DAY")==Pair("0.(3)","DAY"));check(VisibilityScale.normalize("2⁻³","DAY")==Pair("2^-3","DAY"));check(VisibilityScale.normalize("2⁷","YEAR")==Pair("2^7","YEAR"));check(VisibilityScale.normalize("1⁄7","MONTH")==Pair("1/7","MONTH"));check(VisibilityScale.normalize("1/3","DAY")==Pair("1/3","DAY"));check(VisibilityScale.normalize(" 2 ^ 10 / 3 ","MONTH")==Pair("2^10/3","MONTH"));check(VisibilityScale.normalize("1.500e-4","DAY")==Pair("1.500e-4","DAY"));check(VisibilityScale.normalize("1/(2^4)","YEAR").first=="1/(2^4)");check(VisibilityScale.visible(base.copy(maxScaleAmount="0.(3)"),28800.0));check(!VisibilityScale.visible(base.copy(maxScaleAmount="0.(3)"),28800.001));check(VisibilityScale.visible(base.copy(maxScaleAmount="0.1(6)"),14400.0));check(VisibilityScale.visible(base.copy(maxScaleAmount="2⁷"),86400.0*128));check(!VisibilityScale.visible(base.copy(maxScaleAmount="2⁷"),86400.0*129));check(!VisibilityScale.visible(base.copy(maxScaleAmount="0.1(6)"),14400.01));check(VisibilityScale.visible(base,28800.0));check(!VisibilityScale.visible(base,28800.001));check(VisibilityScale.visible(base.copy(maxScaleAmount="2^-3"),10800.0));check(!VisibilityScale.visible(base.copy(maxScaleAmount="2^-3"),10800.01));check(VisibilityScale.visible(base.copy(maxScaleAmount="1/7"),86400.0/7.0));check(!VisibilityScale.visible(base.copy(maxScaleAmount="1/7"),86400.0/7.0+1e-7));check(VisibilityScale.visible(base.copy(maxScaleAmount="2^20/3"),86400.0*1024));check(VisibilityScale.visible(base.copy(maxScaleAmount="1e5"),86400.0*99999));check(!VisibilityScale.visible(base.copy(maxScaleAmount="1e5"),86400.0*100001));check(VisibilityScale.visible(base.copy(maxScaleAmount="1/3",maxScaleUnit="MONTH"),MONTH_SECONDS/3.0));check(!VisibilityScale.visible(base.copy(maxScaleAmount="1/3",maxScaleUnit="MONTH"),MONTH_SECONDS/3.0+0.001));for(expr in listOf("1/0","2^(1/2)","-1","0","2^9999","1e99999","NaN","(1/2","1//2","2^2^2","2^-80","0.(3"))check(runCatching{VisibilityScale.normalize(expr,"DAY")}.isFailure){expr};println("Exact fractional/exponent visibility: PASS")}
